function controlEntry17(){const issues=controlIssues17(),urgent=issues.filter(x=>x.severity===2).length;return `<section class="card control-entry17"><div><span class="eyelabel">ŘÍZENÍ CELÉ SÍTĚ</span><h2>${urgent?'Naléhavé problémy: '+urgent:'Pobočky, lidé a odpovědnost'}</h2><p>${issues.length} sledovaných problémů · ${state.control17.missions.filter(m=>m.status==='active').length} aktivních cílů · ${state.control17.plans.filter(p=>p.status==='pending').length} návrhů ke schválení</p></div><button class="primary" data-control-open17="issues">Otevřít centrum řízení</button></section>`;}
function controlOpen17(tab='issues'){controlTab17=tab;const body=tab==='issues'?controlIssuesHtml17():tab==='managers'?controlManagersHtml17():tab==='standards'?controlStandardsHtml17():controlBoardHtml17();show(`<section class="control-surface17"><span class="eyelabel">VÝSLEDKY STEJNÉ ROZEHRANÉ FIRMY</span><h2>Centrum řízení sítě</h2><div class="control-tabs17" role="tablist" aria-label="Řízení sítě">${Object.entries(CONTROL_TABS17).map(([id,label])=>`<button role="tab" id="controlTab-${id}" data-control-tab17="${id}" aria-controls="controlBody17" aria-selected="${id===tab}" tabindex="${id===tab?0:-1}">${label}</button>`).join('')}</div><div id="controlBody17" role="tabpanel" aria-labelledby="controlTab-${tab}">${body}</div></section>`);el('modalContent').querySelectorAll('[data-control-tab17]').forEach((b,i)=>{b.onclick=()=>{controlOpen17(b.dataset.controlTab17);el(b.id).focus({preventScroll:true});};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=Object.keys(CONTROL_TABS17),j=e.key==='Home'?0:e.key==='End'?keys.length-1:(i+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length;controlOpen17(keys[j]);el('controlTab-'+keys[j]).focus({preventScroll:true});};});controlBind17();}
function controlMetric17(metric,value){return value===null?'Bez výsledku':['profit','branchProfit','debt','dividends'].includes(metric)?money(value):number(value,1)+(metric==='wait'?' min':metric==='lost'?' %':'');}
function controlRoute17(issue){el('modal').close();if(issue.kind==='stock'||issue.kind==='quality')tnStockDialog7(issue.id);else if(issue.kind==='loss'||issue.kind==='queue'||issue.kind==='seats'||issue.kind==='closing')tnDiagnosisDialog7(issue.id);else if(issue.kind==='standard')controlOpen17('standards');else if(['goal','mandate'].includes(issue.kind))controlMissionUI17(issue.id);else if(issue.kind==='approval'){goto('management');tnManageTab7='decisions';render();}else{if(issue.view==='crew')crewSelected5=issue.id;if(issue.view==='menu')menuStore=issue.id;goto(issue.view);}}
function controlIssuesHtml17(){const all=controlIssues17(controlSnoozed17),list=all.filter(x=>(controlCity17==='all'||x.city===controlCity17)&&(controlKind17==='all'||x.kind===controlKind17));return `<div class="control-filter17">${field('Město',`<select id="controlCity17">${option('all','Všechna města',controlCity17)}${[...new Set(state.stores.filter(s=>!s.franchise).map(s=>loc(s.id).city))].map(c=>option(c,c,controlCity17)).join('')}</select>`)}${field('Druh problému',`<select id="controlKind17">${option('all','Všechny problémy',controlKind17)}${Object.entries(CONTROL_ISSUES17).map(([id,label])=>option(id,label,controlKind17)).join('')}</select>`)}<button class="soft" id="controlRules17">Upravit meze upozornění</button></div><label class="checkbox-line"><input type="checkbox" id="controlSnoozed17" ${controlSnoozed17?'checked':''}> Ukázat i odložené problémy</label><p>${list.length} problémů ve filtru · vlastní pobočky: ${state.stores.filter(s=>!s.franchise).length}. Provozní hodnoty jsou z posledního uzavřeného týdne, lidé a mandáty z dnešního stavu.</p><div class="control-list17">${list.map(x=>`<article class="control-issue17 ${x.severity===2?'control-urgent17':''}"><div class="control-card-head17"><strong>${esc(x.name)} · ${CONTROL_ISSUES17[x.kind]}</strong><span>${x.snoozed?'Odloženo do T'+x.until:x.severity===2?'Naléhavé':'K řešení'}</span></div><p>${esc(x.text)}</p><small>${esc(x.city)} · odpovídá ${esc(x.owner)}${x.week?' · uzavřený T'+x.week:''}</small>${x.note?`<p class="control-note17">${esc(x.note)}</p>`:''}<div class="actions"><button class="primary" data-control-issue17="${esc(x.key)}">${x.kind==='stock'?'Prověřit kávu':x.kind==='crew'?'Upravit tým':'Otevřít řešení'}</button><button class="soft" data-control-note17="${esc(x.key)}">Poznámka a odložení</button><button class="quiet" data-control-manager17="${x.id}">Cíl a pravomoci</button></div></article>`).join('')||empty(state.stores.length?'V tomto filtru není žádný problém nad nastavenými mezemi.':'Nejdřív připrav a otevři první kavárnu.')} </div><details class="control-history17"><summary>Historie problémů za posledních 26 týdnů</summary>${state.control17.history.slice().reverse().map(h=>`<p>T${h.week}: ${h.issues.length} problémů · ${h.issues.filter(x=>x.severity===2).length} naléhavých${h.issues.length?' · '+esc(h.issues.slice(0,3).map(x=>loc(x.id).name+': '+CONTROL_ISSUES17[x.kind]).join(', ')):''}</p>`).join('')||'<p>Zatím bez uzavřeného týdne nového přehledu.</p>'}</details>`;}
function controlRulesUI17(){const r=state.control17.rules;show(`<h2>Meze upozornění poboček</h2><p>Upozornění sama nic nemění ani neplatí. Nedostatek kávy a nepokryté směny se zobrazí vždy.</p><div class="fields">${field('Odchody kvůli jednotlivé příčině / % hostů',input('controlLost17',r.lost,1,100,1))}${field('Kvalita nejméně',input('controlQuality17',r.quality,25,99,1))}${field('Únava lidí od',input('controlBurnout17',r.burnout,1,100,1))}${field('Stav zařízení méně než / %',input('controlCondition17',r.condition,1,99,1))}${field('Místní výsledek méně než / Kč',input('controlLoss17',r.loss,-1000000,0,100))}</div><div class="actions"><button class="primary" id="controlRulesSave17">Uložit meze</button><button class="soft" data-control-open17="issues">Zpět bez změny</button></div>`);el('controlRulesSave17').onclick=()=>grToast8(()=>setControlRules17({lost:Number(el('controlLost17').value),quality:Number(el('controlQuality17').value),burnout:Number(el('controlBurnout17').value),condition:Number(el('controlCondition17').value),loss:Number(el('controlLoss17').value)}),()=>controlOpen17('issues'));controlBind17();}
function controlNoteUI17(key){const x=controlIssues17(true).find(x=>x.key===key);if(!x){controlOpen17('issues');return;}show(`<h2>${esc(x.name)} · ${CONTROL_ISSUES17[x.kind]}</h2><p>${esc(x.text)}</p>${field('Poznámka k řešení',`<textarea id="controlNoteText17" rows="3" maxlength="180">${esc(x.note)}</textarea>`)}${field('Odložení',`<select id="controlNoteWeeks17">${[0,1,2,4].map(n=>option(n,n?'Na '+n+' '+(n===1?'týden':'týdny'):'Neodkládat',0)).join('')}</select>`)}<p>Odložení potlačí toto upozornění do zvoleného týdne. Nedostatek kávy ani náklady nezmizí. Po termínu se stále trvající problém vrátí.</p><div class="actions"><button class="primary" id="controlNoteSave17">Uložit poznámku</button><button class="soft" data-control-open17="issues">Zpět bez změny</button></div>`);el('controlNoteSave17').onclick=()=>grToast8(()=>controlNote17(key,el('controlNoteText17').value,Number(el('controlNoteWeeks17').value)),()=>controlOpen17('issues'));controlBind17();}
function controlManagersHtml17(){const own=state.stores.filter(s=>!s.franchise);return `<p>Každý cíl má konkrétního člověka, vlastní období a uložené pravomoci. Náklady na mzdu a zásahy zůstávají ve skutečném provozu.</p><div class="control-grid17">${own.map(s=>{const m=controlMission17(s.id),o=owner5(s),score=m?controlMissionReport17(m):null,p=tnMandate7(s.id);return `<article class="card"><h3>${esc(loc(s.id).name)}</h3><p>${esc(o?.person.name||'Zakladatel')} · ${esc(o?.label||'Osobní řízení')}</p>${m?rows([['Cíl',CONTROL_METRICS17[m.metric].name+' '+controlMetric17(m.metric,m.value)],['Skutečný průměr',controlMetric17(m.metric,score.value)],['Doložené týdny / termín',score.samples+' / '+m.weeks+' · T'+score.due]]):'<p class="sub">Bez dlouhodobého cíle.</p>'}${rows([['Nové závazky nejvýše / týden',money(p.budget)],['Provozní rezerva',p.reserve+' týdny'],['Samostatné řízení',p.enabled&&o?.automatic?'Aktivní':'Vypnuté nebo chybí odpovědný člověk']])}<div class="actions"><button class="primary" data-control-manager17="${s.id}">${m?'Upravit odpovědnost':'Zadat cíl a pravomoci'}</button><button class="soft" data-control-manager-history17="${s.id}">Výsledky a kroky</button></div></article>`;}).join('')||empty('Nejdřív otevři vlastní kavárnu.')} </div>`;}
function controlMissionUI17(id){try{const s=controlOwn17(id),o=owner5(s),m=controlMission17(id),p=tnMandate7(id),metric=m?.metric||'profit';if(!o){show(`<h2>${esc(loc(id).name)} · odpovědnost</h2><p>Pro dlouhodobý cíl potřebuješ obsazeného vedoucího kavárny, regionu nebo provozního ředitele. Zakladatel může kavárnu dál řídit přímo.</p><div class="actions"><button class="primary" id="controlHireManager17">Obsadit vedení</button><button class="soft" data-control-open17="managers">Zpět do přehledu</button></div>`);el('controlHireManager17').onclick=()=>{el('modal').close();goto('people');};controlBind17();return;}show(`<h2>${esc(loc(id).name)} · cíl manažera</h2><p>Odpovídá ${esc(o.person.name)} · ${esc(o.label)}. Nový cíl ukončí předchozí období a zachová jeho výsledky.</p><div class="fields">${field('Měřitelný cíl',`<select id="controlMissionMetric17">${Object.entries(CONTROL_METRICS17).map(([k,c])=>option(k,c.name,metric)).join('')}</select>`)}${field('Cílová hodnota',input('controlMissionValue17',m?.value??0,CONTROL_METRICS17[metric].min,CONTROL_METRICS17[metric].max,1))}${field('Období skutečných týdnů',`<select id="controlMissionWeeks17">${[4,8,13].map(n=>option(n,n+' týdnů',m?.weeks||4)).join('')}</select>`)}${field('Nové závazky nejvýše / týden',input('controlMissionBudget17',p.budget,0,100000,500))}${field('Ruční schválení nad / Kč',input('controlMissionApproval17',p.approval,0,100000,500))}${field('Chráněná rezerva / týdny',input('controlMissionReserve17',p.reserve,1,8,1))}${field('Cena kávy nejméně / Kč',input('controlMissionMin17',p.minPrice,40,400,1))}${field('Cena kávy nejvýše / Kč',input('controlMissionMax17',p.maxPrice,40,400,1))}${field('Čekání nejvýše / minuty',input('controlMissionWait17',p.wait,0,30,1))}${field('Kvalita nejméně',input('controlMissionQuality17',p.quality,25,99,1))}</div><fieldset class="control-rights17"><legend>Povolené zásahy</legend>${TN_RIGHTS7.map(k=>`<label><input type="checkbox" data-control-right17="${k}" ${p.rights[k]?'checked':''}> ${esc(TN_RIGHT_LABELS7[k])}</label>`).join('')}</fieldset><label class="checkbox-line"><input type="checkbox" id="controlMissionEnabled17" ${p.enabled?'checked':''}> Povolit samostatné zásahy v tomto mandátu</label><p>Nový nábor, vybavení a jiná káva vždy vyžadují schválení. Rozpočet zahrnuje jednorázovou platbu i nové týdenní závazky. Uzamčené části standardu mají přednost; ruční rozpis se nepřepisuje.</p><div class="actions"><button class="primary" id="controlMissionSave17">Uložit cíl a mandát</button><button class="soft" data-control-open17="managers">Zpět bez změny</button>${m?'<button class="quiet" id="controlMissionStop17">Ukončit sledování cíle</button>':''}</div>`);el('controlMissionMetric17').onchange=()=>{const c=CONTROL_METRICS17[el('controlMissionMetric17').value],input=el('controlMissionValue17');input.min=c.min;input.max=c.max;input.value=el('controlMissionMetric17').value==='quality'?80:el('controlMissionMetric17').value==='wait'?8:el('controlMissionMetric17').value==='lost'?20:el('controlMissionMetric17').value==='served'?600:0;};el('controlMissionSave17').onclick=()=>grToast8(()=>{const metric=el('controlMissionMetric17').value,num=id=>Number(el(id).value);return setControlMission17(id,{metric,value:num('controlMissionValue17'),weeks:num('controlMissionWeeks17'),policy:{enabled:el('controlMissionEnabled17').checked,goal:CONTROL_METRICS17[metric].goal,budget:num('controlMissionBudget17'),approval:num('controlMissionApproval17'),reserve:num('controlMissionReserve17'),minPrice:num('controlMissionMin17'),maxPrice:num('controlMissionMax17'),wait:num('controlMissionWait17'),quality:num('controlMissionQuality17'),rights:Object.fromEntries([...el('modalContent').querySelectorAll('[data-control-right17]')].map(e=>[e.dataset.controlRight17,e.checked]))}});},()=>controlOpen17('managers'));if(el('controlMissionStop17'))el('controlMissionStop17').onclick=()=>grToast8(()=>stopControlMission17(id),()=>controlOpen17('managers'));controlBind17();}catch(e){toast(e.message);}}
function controlMissionHistoryUI17(id){const missions=state.control17.missions.filter(m=>m.target===id).slice().sort((a,b)=>b.start-a.start);show(`<h2>${esc(loc(id).name)} · odpovědnost a výsledky</h2>${missions.map(m=>{const r=controlMissionReport17(m),decisions=state.tycoon7.decisions.filter(d=>m.decisions.includes(d.id));return `<article class="control-history17"><h3>${esc(m.name)} · ${CONTROL_STATUS17[m.status]}</h3>${rows([['Tehdejší cíl',CONTROL_METRICS17[m.metric].name+' '+controlMetric17(m.metric,m.value)],['Skutečný průměr / doložené týdny',controlMetric17(m.metric,r.value)+' · '+r.samples+' / '+m.weeks],['Začátek / termín','T'+m.start+' / T'+r.due],['Výsledek',m.status==='reviewed'?(r.met?'Splněno':'Nesplněno'):'Období není úplně vyhodnocené']])}<details><summary>Týdenní výsledky a rozhodnutí</summary>${m.samples.map(x=>`<p>T${x.week}: ${x.frame?controlMetric17(m.metric,x.frame[m.metric]):'Bez skutečného provozního výsledku'}</p>`).join('')}${decisions.map(d=>`<article><strong>T${d.week} · ${esc(d.action.label)}</strong><p>${esc(d.reason)}</p>${rows([['Platba / nový týdenní závazek',money(d.cost)+' / '+money(d.weekly)],['Odhad / skutečný místní zisk',money(d.expected.profit)+' / '+(d.actual?money(d.actual.profit):'Čeká na provoz')]])}</article>`).join('')||'<p>V uchovaném archivu nejsou provedené kroky tohoto cíle.</p>'}</details></article>`;}).join('')||empty('Tato pobočka zatím nemá nové období odpovědnosti.')}<p>Výsledek zahrnuje ceny, zásoby, tým i další vlivy. Změna vedení ukončí původní odpovědnost; nástupce má vlastní cíl.</p><button class="soft" data-control-open17="managers">Zpět k manažerům</button>`);controlBind17();}
function controlStandardsHtml17(){const stores=state.stores.filter(s=>!s.franchise&&!grTemporary8(s.id));controlSelected17=controlSelected17.filter(id=>stores.some(s=>s.id===id)&&state.control17.assignments[id]);return `<div class="actions"><button class="primary" id="controlCapture17" ${!stores.length?'disabled':''}>Vytvořit koncept z vlastní kavárny</button><button class="soft" id="controlOpeningStandard17">Návrhy pro nové kavárny</button></div><p>Koncept obsahuje značku, vlastní dispozici, vybavení, menu, směny a kávu. Přidělení nic nenakupuje. Rozdíly zavede až schválený placený program.</p><div class="control-grid17">${stores.map(s=>{const a=state.control17.assignments[s.id],audit=a?controlStandard17(s.id):null;return `<article class="card"><h3>${esc(loc(s.id).name)}</h3>${audit?`<label class="checkbox-line"><input type="checkbox" data-control-select17="${s.id}" ${controlSelected17.includes(s.id)?'checked':''}> Vybrat do zavádění</label><p>${esc(audit.name)} · ${audit.compliant?'Splňuje sledovaný standard':esc(audit.differences.join(' · '))}</p><small>Cíl podané kvality ${a.quality}; kvalita se skutečně měří, nepřiděluje zdarma.</small>${Object.entries(a.exceptions).map(([k,e])=>`<p class="control-note17">${CONTROL_MODULES17[k]} · ${e.until>=state.week?'výjimka do T'+e.until:'výjimka vypršela'}: ${esc(e.reason)}</p>`).join('')}`:'<p>Koncept zatím nepřidělený.</p>'}<div class="actions"><button class="soft" data-control-assign17="${s.id}">Přidělit koncept</button>${a?`<button class="soft" data-control-exception17="${s.id}">Místní výjimka</button>`:''}</div></article>`;}).join('')||empty('Potřebuješ vlastní stálou kavárnu.')} </div><div class="fields">${field('Limit celého zavedení / Kč',input('controlRolloutBudget17',250000,0,10000000,1000))}${field('Chráněná rezerva / týdny',input('controlRolloutReserve17',3,1,8,1))}</div><button class="primary" id="controlRolloutQuote17">Prověřit vybrané pobočky</button><h3>Schválené programy</h3>${state.control17.programs.slice().sort((a,b)=>b.start-a.start).map(p=>`<details class="control-history17"><summary>${CONTROL_STATUS17[p.status]} · ${p.steps.length} / ${p.targets.length} poboček · ${money(p.spent)}</summary><p>${esc(p.reason)}</p>${p.steps.map(s=>`<p>T${s.week} · ${esc(loc(s.id).name)} · ${money(s.cost)} · ${s.actual?money(s.actual.profit)+' skutečný místní zisk':'Čeká na provoz'}</p>`).join('')}${p.status==='active'?`<button class="soft" data-control-rollout-stop17="${p.id}">Zastavit další kroky</button>`:''}</details>`).join('')||'<p class="sub">Žádný nový program zavádění.</p>'}`;}
function controlCaptureUI17(){const stores=state.stores.filter(s=>!s.franchise&&!grTemporary8(s.id));show(`<h2>Vlastní koncept kavárny</h2><div class="fields">${field('Vzorová kavárna',`<select id="controlCaptureStore17">${stores.map(s=>option(s.id,loc(s.id).name,stores[0]?.id)).join('')}</select>`)}${field('Název konceptu',`<input id="controlCaptureName17" maxlength="40" placeholder="Např. Komunitní kavárna">`)}</div><p>Uloží se nynější vybavení, dispozice, menu, směny, receptura a značka. Stejný návrh bude dostupný při založení nové kavárny.</p><div class="actions"><button class="primary" id="controlCaptureSave17">Uložit koncept</button><button class="soft" data-control-open17="standards">Zpět bez změny</button></div>`);el('controlCaptureSave17').onclick=()=>grToast8(()=>captureStandard8(el('controlCaptureStore17').value,el('controlCaptureName17').value),()=>controlOpen17('standards'));controlBind17();}
